import unittest

from ledger.accounts import load_chart


class Chart(unittest.TestCase):
    def test_a_chart_file_by_code(self):
        c = load_chart("code,name,kind\n2000,Payables,liability\n1000,Cash,asset\n")
        self.assertEqual([a.code for a in c], ["1000", "2000"])

    def test_a_code_twice_is_refused(self):
        with self.assertRaises(ValueError):
            load_chart("code,name,kind\n1000,Cash,asset\n1000,Bank,asset\n")


if __name__ == "__main__":
    unittest.main()
